bool InRanges(const uint16_t (*r)[2], size_t n, int code) {
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (code < r[mid][0]) {
            hi = mid;
        } else if (code > r[mid][1]) {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

bool InAstralSet(int code, const uint32_t* set, size_t n) {
    long pos = 0x10000;
    for (size_t i = 0; i + 1 < n; i += 2) {
        pos += static_cast<long>(set[i]);
        if (pos > code) return false;
        pos += static_cast<long>(set[i + 1]);
        if (pos >= code) return true;
    }
    return false;
}

