bool IsIdentifierStart(int code, bool astral) {
    if (code < 65) return code == 36;
    if (code < 91) return true;
    if (code < 97) return code == 95;
    if (code < 123) return true;
    if (code <= 0xffff) return code >= 0xaa && InRanges(kIdStartBmp, std::size(kIdStartBmp), code);
    if (!astral) return false;
    return InAstralSet(code, kAstralIdStart, std::size(kAstralIdStart));
}

bool IsIdentifierChar(int code, bool astral) {
    if (code < 48) return code == 36;
    if (code < 58) return true;
    if (code < 65) return false;
    if (code < 91) return true;
    if (code < 97) return code == 95;
    if (code < 123) return true;
    if (code <= 0xffff) return code >= 0xaa && InRanges(kIdCharBmp, std::size(kIdCharBmp), code);
    if (!astral) return false;
    return InAstralSet(code, kAstralIdStart, std::size(kAstralIdStart)) ||
           InAstralSet(code, kAstralIdChar, std::size(kAstralIdChar));
}

int XhtmlEntityCode(std::u16string_view name) {
    size_t lo = 0, hi = std::size(kXhtmlEntities);
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        const char* k = kXhtmlEntities[mid].name;
        size_t i = 0;
        int cmp = 0;
        for (;; ++i) {
            bool ke = k[i] == 0, ne = i >= name.size();
            if (ke || ne) {
                cmp = ke && ne ? 0 : (ke ? -1 : 1);
                break;
            }
            int a = static_cast<unsigned char>(k[i]), b = name[i];
            if (a != b) {
                cmp = a < b ? -1 : 1;
                break;
            }
        }
        if (cmp == 0) return kXhtmlEntities[mid].code;
        if (cmp < 0) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return -1;
}

